#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <stdint.h>

int main(int argc, char **argv) {
    if (argc < 4) {
        puts("NO_INPUT");
        return 0;
    }
    char *end;
    // Parse base
    long long base = strtoll(argv[1], &end, 10);
    if (end == argv[1]) { // no conversion
        puts("BAD_INPUT");
        return 0;
    }
    // Parse exponent
    long long exp = strtoll(argv[2], &end, 10);
    if (end == argv[2]) {
        puts("BAD_INPUT");
        return 0;
    }
    // Parse modulus
    long long mod = strtoll(argv[3], &end, 10);
    if (end == argv[3]) {
        puts("BAD_INPUT");
        return 0;
    }
    // Validate modulus
    if (mod < 1) {
        puts("BAD_MODULUS");
        return 0;
    }
    if (mod > 1000000000LL) {
        puts("OUT_OF_RANGE");
        return 0;
    }
    // Validate exponent
    if (exp < 0) {
        puts("NEGATIVE_EXPONENT");
        return 0;
    }
    // Reduce base modulo mod, make it positive
    base %= mod;
    if (base < 0) base += mod;
    // Modular exponentiation (square‑and‑multiply)
    long long result = 1 % mod;
    unsigned long long e = (unsigned long long)exp;
    long long b = base;
    while (e) {
        if (e & 1ULL) {
            __int128 tmp = ( __int128) result * b;
            result = (long long)(tmp % mod);
        }
        __int128 sq = ( __int128) b * b;
        b = (long long)(sq % mod);
        e >>= 1ULL;
    }
    printf("result=%lld\n", result);
    return 0;
}
